import type { createAdmin } from "arky-sdk/admin";
import type {
  ActOnFulfillmentJobParams,
  ActOnFulfillmentParams,
  CreateFulfillmentParams,
  DeliveryStatus,
  FindFulfillmentJobsParams,
  FindFulfillmentsParams,
  Fulfillment,
  FulfillmentAction,
  FulfillmentAssignmentSource,
  FulfillmentExecution,
  FulfillmentJob,
  FulfillmentJobAction,
  FulfillmentJobItem,
  FulfillmentJobLine,
  FulfillmentJobMethod,
  FulfillmentJobMoveLine,
  FulfillmentJobStatus,
  FulfillmentLine,
  FulfillmentJobBuyer,
  FulfillmentJobContact,
  FulfillmentRouting,
  FulfillmentType,
  FulfillmentUnitSlots,
  GetFulfillmentJobParams,
  GetFulfillmentParams,
  GetFulfillmentRoutingParams,
  LocationPick,
  MarkFulfillmentDeliveredParams,
  PickupStatus,
  ResolveFulfillmentUnitSlotsParams,
  RoutingAssign,
  RoutingCondition,
  RoutingRule,
  RoutingRuleStatus,
  RoutingSplit,
  RoutingTarget,
  Tracking,
  UpdateFulfillmentRoutingParams,
  UpdateFulfillmentTrackingParams,
  RecordPickupCashParams,
  PickupCash,
  Payment,
  Money,
  EpochMilliseconds,
  OrderDeliveryTiming,
  CustomerOrderFulfillment,
} from "arky-sdk";
import type { Fulfillment as PublicFulfillment, PaginatedResponse } from "arky-sdk/types";
import { selectFulfillmentMoveUnits, selectFulfillmentUnits } from "arky-sdk/utils";

type Assert<T extends true> = T;
type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;
type Missing<T, K extends PropertyKey> = K extends keyof T ? false : true;
type RequiredField<T, K extends keyof T> = {} extends Pick<T, K> ? false : true;
type Api = ReturnType<typeof createAdmin>["eshop"];

export type FulfillmentHistoryContract = [
  Assert<Equal<Fulfillment, PublicFulfillment>>,
  Assert<Equal<keyof Api["fulfillment"], "create" | "execute" | "find" | "get" | "updateTracking" | "markDelivered">>,
  Assert<Equal<Awaited<ReturnType<Api["fulfillment"]["find"]>>, PaginatedResponse<Fulfillment>>>,
  Assert<Equal<Parameters<Api["fulfillment"]["find"]>[0], FindFulfillmentsParams>>,
  Assert<Equal<Parameters<Api["fulfillment"]["get"]>[0], GetFulfillmentParams>>,
  Assert<Equal<Parameters<Api["fulfillment"]["create"]>[0], CreateFulfillmentParams>>,
  Assert<Equal<Parameters<Api["fulfillment"]["execute"]>[0], ActOnFulfillmentParams>>,
  Assert<Equal<Parameters<Api["fulfillment"]["updateTracking"]>[0], UpdateFulfillmentTrackingParams>>,
  Assert<Equal<Parameters<Api["fulfillment"]["markDelivered"]>[0], MarkFulfillmentDeliveredParams>>,
  Assert<Equal<Awaited<ReturnType<Api["fulfillment"]["execute"]>>, Fulfillment>>,
  Assert<Equal<keyof Fulfillment, "id" | "store_id" | "fulfillment_job_id" | "created_by" | "lines" | "type" | "created_at" | "updated_at">>,
  Assert<Missing<Fulfillment, "request_id" | "status" | "tracking" | "delivered_at">>,
  Assert<Equal<FulfillmentType["type"], "delivery" | "pickup">>,
  Assert<Equal<Extract<FulfillmentType, { type: "delivery" }>["trackings"], Tracking[]>>,
  Assert<Equal<DeliveryStatus["type"], "preparing" | "dispatched" | "delivered" | "cancelled">>,
  Assert<Equal<PickupStatus["type"], "preparing" | "ready" | "collected" | "cancelled">>,
  Assert<Equal<Extract<DeliveryStatus, { type: "dispatched" }>["execution"], FulfillmentExecution>>,
  Assert<Equal<FulfillmentAction["type"], "ready" | "fulfill" | "cancel">>,
  Assert<RequiredField<Extract<FulfillmentAction, { type: "fulfill" }>, "timing">>,
  Assert<Equal<ReturnType<typeof selectFulfillmentUnits>, FulfillmentLine>>,
  Assert<Equal<ReturnType<typeof selectFulfillmentMoveUnits>, FulfillmentJobMoveLine>>,
  Assert<Equal<keyof FulfillmentLine, "fulfillment_job_line_id" | "unit_spans" | "selected_units" | "lot_reference">>,
  Assert<Equal<FulfillmentLine["lot_reference"], string | null>>,
  Assert<Equal<keyof FindFulfillmentsParams, "store_id" | "order_id" | "fulfillment_job_id" | "rental_id" | "limit" | "cursor">>,
  Assert<Missing<Api, "shipment" | "pickup" | "invoice" | "shippingLabel" | "shippingLabelRefund" | "merchantDebit" | "merchantDebitReversal">>,
];

export type FulfillmentJobContract = [
  Assert<Equal<FulfillmentJob["method"], FulfillmentJobMethod>>,
  Assert<Equal<FulfillmentJobMethod["type"], "delivery" | "pickup">>,
  Assert<Equal<Extract<FulfillmentJobMethod, { type: "delivery" }>["source"], FulfillmentAssignmentSource>>,
  Assert<Equal<FulfillmentAssignmentSource["type"], "served_from" | "routing_rule" | "otherwise" | "account">>,
  Assert<Equal<FulfillmentJobStatus, "scheduled" | "on_hold" | "open" | "in_progress" | "completed" | "cancelled">>,
  Assert<Equal<keyof FulfillmentJob, "id" | "store_id" | "type" | "method" | "holds" | "contact" | "status" | "created_at" | "updated_at">>,
  Assert<Missing<FulfillmentJob, "recipient">>,
  Assert<Equal<FulfillmentJob["contact"], FulfillmentJobContact>>,
  Assert<Equal<FulfillmentJobContact, { email: string | null; first_name: string | null; last_name: string | null; phone: string | null; buyer: FulfillmentJobBuyer }>>,
  Assert<Equal<FulfillmentJobBuyer, { type: "customer"; customer_id: string } | { type: "company"; company_id: string; company_name: string } | { type: "company_location"; company_id: string; company_name: string; company_location_id: string; company_location_name: string }>>,
  Assert<Equal<Extract<FulfillmentJob["type"], { type: "order_delivery" }>["timing"], OrderDeliveryTiming>>,
  Assert<Equal<CustomerOrderFulfillment["timing"], OrderDeliveryTiming>>,
  Assert<Equal<Extract<FulfillmentJob["type"], { type: "order_delivery" }>["lines"], FulfillmentJobLine[]>>,
  Assert<Equal<Extract<FulfillmentJob["type"], { type: "rental_replacement" }>["line"], FulfillmentJobLine>>,
  Assert<Equal<keyof FulfillmentJobLine, "id" | "source" | "inventory_requirements" | "quantity" | "fulfilled_quantity" | "cancelled_units" | "moved_units">>,
  Assert<Equal<keyof Api["fulfillmentRouting"], "get" | "update">>,
  Assert<Equal<Parameters<Api["fulfillmentRouting"]["get"]>[0], GetFulfillmentRoutingParams>>,
  Assert<Equal<Parameters<Api["fulfillmentRouting"]["update"]>[0], UpdateFulfillmentRoutingParams>>,
  Assert<Equal<Awaited<ReturnType<Api["fulfillmentRouting"]["update"]>>, FulfillmentRouting>>,
  Assert<Equal<keyof RoutingRule, "id" | "key" | "conditions" | "target" | "status">>,
  Assert<Equal<RoutingCondition["type"], "markets" | "sales_channels" | "zones" | "shipping_profiles">>,
  Assert<Equal<RoutingTarget, { location_ids: string[]; assign: RoutingAssign }>>,
  Assert<Equal<RoutingAssign, { type: "manual" } | { type: "automatic"; pick: LocationPick; split: RoutingSplit }>>,
  Assert<Equal<LocationPick["type"], "in_list_order" | "most_stock">>,
  Assert<Equal<RoutingSplit["type"], "never" | "when_needed">>,
  Assert<Equal<RoutingRuleStatus["type"], "active" | "paused">>,
  Assert<Equal<keyof Api["fulfillmentJob"], "find" | "get" | "items" | "unitSlots" | "decide" | "getPickupCash" | "recordPickupCash">>,
  Assert<Equal<Parameters<Api["fulfillmentJob"]["getPickupCash"]>[0], GetFulfillmentJobParams>>,
  Assert<Equal<Awaited<ReturnType<Api["fulfillmentJob"]["getPickupCash"]>>, PickupCash | null>>,
  Assert<Equal<PickupCash, { payment_id: string; payment_updated_at: EpochMilliseconds; due: Money }>>,
  Assert<Equal<Parameters<Api["fulfillmentJob"]["recordPickupCash"]>[0], RecordPickupCashParams>>,
  Assert<Equal<Awaited<ReturnType<Api["fulfillmentJob"]["recordPickupCash"]>>, Payment>>,
  Assert<Equal<RecordPickupCashParams, { store_id: string; fulfillment_job_id: string; id: string; payment_id: string; expected_job_updated_at: EpochMilliseconds; expected_payment_updated_at: EpochMilliseconds; money: Money; reference: string | null }>>,
  Assert<Missing<Api, "fulfillmentOrder" | "fulfillmentPartner" | "fulfillmentRoutingPolicy">>,
  Assert<Equal<Parameters<Api["fulfillmentJob"]["find"]>[0], FindFulfillmentJobsParams>>,
  Assert<Equal<keyof FindFulfillmentJobsParams, "store_id" | "order_id" | "rental_id" | "store_location_id" | "hold" | "inventory_item_id" | "status" | "scheduled_from" | "scheduled_to" | "sort_field" | "sort_direction" | "limit" | "cursor">>,
  Assert<Equal<Parameters<Api["fulfillmentJob"]["get"]>[0], GetFulfillmentJobParams>>,
  Assert<Equal<Awaited<ReturnType<Api["fulfillmentJob"]["items"]>>, FulfillmentJobItem[]>>,
  Assert<Equal<keyof FulfillmentJobItem, "fulfillment_job_line_id" | "order_number" | "product_key" | "product_blocks" | "variant_sku" | "image" | "quantity" | "source">>,
  Assert<Equal<Parameters<Api["fulfillmentJob"]["unitSlots"]>[0], ResolveFulfillmentUnitSlotsParams>>,
  Assert<Equal<Awaited<ReturnType<Api["fulfillmentJob"]["unitSlots"]>>, FulfillmentUnitSlots>>,
  Assert<Equal<Parameters<Api["fulfillmentJob"]["decide"]>[0], ActOnFulfillmentJobParams>>,
  Assert<Equal<ActOnFulfillmentJobParams["action"], FulfillmentJobAction>>,
  Assert<Equal<Awaited<ReturnType<Api["fulfillmentJob"]["decide"]>>, FulfillmentJob>>,
];
